namespace DpiShell.App;

/// <summary>
/// Тексты кнопок «(i)» — дословно из docs/10-info-texts.md (обратные кавычки разметки убраны). Ключ — заголовок раздела в документе.
/// Здесь и только здесь: в XAML — лишь ключ (InfoButton.Topic). Тест окна сверяет тексты с документом.
/// </summary>
public static class InfoTexts
{
    public const string Home = "Главная — режим службы и стратегия";
    public const string Select = "Подбор — быстрый / полный / глубокий";
    public const string Targets = "Свои адреса";
    public const string DomainLists = "Списки доменов";
    public const string IpLists = "IP-списки";
    public const string Game = "Игровой режим";
    public const string Hosts = "hosts — «Починить адреса»";
    public const string Dns = "DNS";
    public const string Diag = "Диагностика";

    public static readonly IReadOnlyDictionary<string, string> All = new Dictionary<string, string>
    {
        [Home] = "Здесь включается обход блокировок для всего компьютера. «Включить» запускает его как службу Windows: он работает и после перезагрузки, окно программы держать открытым не нужно. Стратегия — это способ, которым обход обманывает оборудование провайдера; у разных провайдеров работают разные. Если не знаете, какую выбрать, — не выбирайте: нажмите «Подобрать», программа проверит сама и включит лучшую. Менять стратегию вручную имеет смысл, только если подбор не помог или вы хотите сравнить. При смене стратегии служба перезапускается — открытые соединения на секунду прервутся.",
        [Select] = "Подбор перебирает стратегии и проверяет, открываются ли YouTube, Discord и ваши адреса. «Быстрый» останавливается на первой, у которой всё открылось, — обычно 1–3 минуты. «Полный» проверяет все и показывает таблицу — полезно, если хотите самую надёжную. «Глубокий» дополнительно придумывает новые стратегии, когда готовые не помогли; это долго (до получаса). Во время подбора обход несколько раз включается и выключается — сайты и игры будут прерываться, лучше ничего важного в это время не делать. Закончившийся подбор сам включает лучшую стратегию.",
        [Targets] = "Сюда добавляют сайты, которые должны открываться, кроме YouTube и Discord: например, example.com или полную ссылку. Эти адреса проверяются при подборе и автоматически попадают в список обхода. Отметьте «важный», если без этого сайта подбор считать неудачным. Не добавляйте сайты, которые и так открываются: обход для них ничего не улучшит, а в редких случаях может помешать. Если сайт перестал открываться после добавления — уберите его или добавьте в исключения.",
        [DomainLists] = "Обход применяется не ко всему интернету, а только к сайтам из списков — так он не мешает всему остальному. Стандартные списки (YouTube, Discord и другие известные заблокированные сайты) приходят с обновлениями, править их нельзя. Свои сайты добавляйте в «Свои адреса», а сайты, которые обход ломает, — в «Исключения». Если какой-то сайт открывается без обхода, его в списках быть не должно. Поддомены учитываются сами: строка example.com покрывает и video.example.com.",
        [IpLists] = "Некоторые программы и игры не сообщают, к какому сайту идут, — только адрес (IP). Для них обход включается по списку адресов крупных сетей (Cloudflare, Google, игровые и хостинг-компании). «По списку» нужен для игр, голосовых программ и сайтов, которые замедляют целиком; для YouTube и Discord он не требуется. «Все адреса» — обход для любого соединения без проверки: это только чтобы быстро понять, поможет ли обход вообще, — многие сайты при этом начинают работать с ошибками, поэтому режим сам выключается через 10 минут. Список обновляется вместе с данными программы; свои подсети можно добавить рядом.",
        [Game] = "Игры ходят не по «сайтовым» портам, а по случайным, поэтому обычный обход их не видит. Игровой режим включает обход на всех этих портах, но только к адресам из IP-списка, и подсовывает «приманку» в первые пакеты каждого соединения. Включайте, если игра не подключается к серверам или голосовой чат в игре не работает, а без обхода — тем более. Не включайте «на всякий случай»: растёт нагрузка на процессор (особенно при торрентах), может вырасти задержка (пинг), а некоторые программы (VPN, удалённый рабочий стол) могут начать сбоить. Если после включения что-то стало хуже — просто выключите.",
        [Hosts] = "Иногда провайдер блокирует не сайт, а конкретный адрес сервера — тогда ни обход, ни другой DNS не помогают, но у сайта есть другие адреса. Программа может записать такие адреса в системный файл hosts (список «сайт → адрес», который Windows смотрит раньше DNS) — только для GitHub, Telegram и Discord и только после проверки, что адрес действительно принадлежит этому сайту и отвечает. Делайте это, если не качаются файлы с GitHub, не открывается веб-версия Telegram или Discord запускается несколько минут. Записи помечены блоком «DpiShell», другие строки файла не меняются; копия файла сохраняется, «Вернуть как было» убирает только наши строки. Защитник Windows может предупредить об изменении hosts — это его реакция на любую правку этого файла. Устаревшие адреса программа проверяет раз в день и убирает сама.",
        [Dns] = "DNS переводит имя сайта в адрес. Некоторые провайдеры подменяют ответы: сайт «не существует», хотя он есть; браузеры обходят это сами, а программы (Discord, игры) — нет. «Проверить DNS» сравнивает ответы вашего DNS с защищённым (DoH — запросы шифруются, провайдер их не видит и не подменяет). Если провайдер подменяет ответы, программа подскажет, как включить защищённый DNS в настройках Windows — сама она их не меняет. Не включайте его, если компьютер в рабочей сети с внутренними адресами или вы пользуетесь фильтрами роутера: они перестанут действовать. Выключить можно там же, в настройках Windows. DNS не чинит блокировку по адресу — для этого есть «Починить адреса».",
        [Diag] = "Здесь программа проверяет, что мешает обходу: другие программы обхода (их надо остановить), VPN, антивирусные и «игровые» сетевые службы, настройки прокси, подмену DNS, лишние строки в hosts. Зайдите сюда, если «Включено», а сайты не открываются, или перед тем, как писать о проблеме. Ничего не меняется без вашей кнопки: у каждой находки написано, что сделать. «Сохранить отчёт» собирает журнал в файл — без паролей и личных данных — его можно прикрепить к вопросу.",
    };

    public static string Get(string? topic) => topic is not null && All.TryGetValue(topic, out var t) ? t : "";
}
